            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Gece en karanlık ve ebedi göründüğü zaman gün ışığı en yakındır. Her gecenin bir sabahı vardır.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Hükûmetler düşmanımız, milletler dostumuz ve kalbimizdeki haklı isyan kuvvetimizdir.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Çanakkale'de dövüşürken ne asi ne esirdik. Namuslu bir millet gibi dövüştük, öldük, öldürüldük.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Hayat bana en korkak adamların iddia ve cesaretten bahsedenler olduğunu öğretti.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Ateşten gömlek taşıyanlar sıcağın ısıttığı kadar yaktığını da bilirler.", Author = "Halide Edib Adıvar" },
