            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "İnsan biraz gevezelik etmezse dili paslanıyor.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Fikir gidince insan da kâğıt gibi cansız, manasız oluyor.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Namus kadının yüzünü açıp açmamasında değildir. Din de peçe demek değildir. Öyle kapalı kadınlar vardır ki kapı arasından her türlü rezaleti yaparlar.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Zavallı küçük kız bilmiyordu ki, aynı kudretle birbirine bağlı olan büyük aşkların hepsi masallardadır.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "İnsanların en etkili silahı, samimiyet ve zekadır.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Hayatın bazı öncesiz anları vardır ki ne süresi ne biçimi ne tanımı vardır. Yalnızca bir duygulanma, yalnızca bir hayat sarsıntısıdır.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Ben bu bayrağın altında doğmuş bir Türk kadınıyım. Burada yaşadım, burada öleceğim.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Anladık ki insan sürülebilir, hatta imha edilebilir, fakat fikir öyle değil. Fikir kafadan kafaya, devirden devire atlar geçer ve kendini gösterir.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Milletinin ve memleketinin geleceği tehlikede olmamak şartıyla ben daima savaşa karşıyım.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Biz çabuk inanan, yufka yürekli insanlarız.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Hayat, sinemadan başka bir şey değil. Tek farkı, sinema adama daha fazla heyecan veriyor.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Türkiye sahiden çiğnenmeyecek kadar büyük lokmadır. İngiltere, lokmanın kenarlarını Yunanistan'a çiğnetmek istiyor.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Türkler her türlü haksızlığı, hatta fenalığı affedebilirler, fakat onurlarına dokunulduğu zaman mesele bütün bütün değişir.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Benim için, içinde bulunduğumuz tehlikeler ve çektiğimiz zahmetler acınacak değil, şeref verecek bir vaziyetti.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Sevmek kafa ile düşünmeyle değildir. Sevmek... Sevmektir işte!", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Birbirimize ruhumuzun çirkin taraflarını görecek kadar yaklaşmadan ayrılmak belki daha iyi.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "İnsan gençliğinde kalbine ne kadar çok his ve hatıra biriktirirse o kadar geç ihtiyar olur. İnsana ekmekten, sudan fazla his lazım.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "İnsanın söktürdüğü dişinin yeri de bazen ağrır ve ağrı hiç de diş ağrısı değildir.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Felaket ve tehlike önünde birleşen kalpler, düşmana karşı birbirine kenetlenen eller toptan tüfekten müessir müdafaalardır.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Aşk en ulvi nikahtır. İki kişiyi ondan başka bir şey bağlayamaz.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Anlıyorum ki sevmekte niçin ve nasıl kat'iyen yoktur.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "Demek ki biz zavallı insanlar kalplerimizin elinde birer oyuncaktan başka bir şey değiliz.", Author = "Halide Edib Adıvar" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Halide_Edib_Adıvar", Text = "İnsanlar, yerler, çerçeveler değişiyor; fakat acılar, aşklar, şairler hep aynı!", Author = "Halide Edib Adıvar" },
